import type { PinDefinition } from '../types';

export interface ComponentMetadata {
  type: string;
  name: string;
  category: 'controllers' | 'prototyping' | 'outputs' | 'sensors' | 'passive' | 'other';
  width: number;
  height: number;
  pins: PinDefinition[];
  description: string;
  defaultProperties: Record<string, any>;
}

// Helper to generate breadboard pins
const generateBreadboardPins = (): PinDefinition[] => {
  const pins: PinDefinition[] = [];
  
  // Power rails: Top (- and +) and Bottom (+ and -)
  // 30 columns for power rails, spaced out
  const colSpacing = 15;
  const startX = 50;
  
  for (let i = 0; i < 30; i++) {
    pins.push({
      id: `rail_top_neg_${i}`,
      name: `-`,
      x: startX + i * colSpacing,
      y: 15,
      type: 'gnd',
    });
    pins.push({
      id: `rail_top_pos_${i}`,
      name: `+`,
      x: startX + i * colSpacing,
      y: 30,
      type: 'power',
    });
  }

  const terminalTopY = 60;
  const rowSpacing = 15;
  const terminalBottomY = 165;

  for (let col = 0; col < 30; col++) {
    const cx = startX + col * colSpacing;
    // Upper terminal strip: Rows f, g, h, i, j
    const upperRows = ['f', 'g', 'h', 'i', 'j'];
    upperRows.forEach((row, rowIndex) => {
      pins.push({
        id: `hole_${row}_${col + 1}`,
        name: `${row}${col + 1}`,
        x: cx,
        y: terminalTopY + rowIndex * rowSpacing,
        type: 'passive',
      });
    });

    // Lower terminal strip: Rows a, b, c, d, e
    const lowerRows = ['a', 'b', 'c', 'd', 'e'];
    lowerRows.forEach((row, rowIndex) => {
      pins.push({
        id: `hole_${row}_${col + 1}`,
        name: `${row}${col + 1}`,
        x: cx,
        y: terminalBottomY + rowIndex * rowSpacing,
        type: 'passive',
      });
    });
  }

  // Bottom Rails (Y: 255 and Y: 270)
  const bottomRailY = 255;
  for (let i = 0; i < 30; i++) {
    pins.push({
      id: `rail_bot_neg_${i}`,
      name: `-`,
      x: startX + i * colSpacing,
      y: bottomRailY,
      type: 'gnd',
    });
    pins.push({
      id: `rail_bot_pos_${i}`,
      name: `+`,
      x: startX + i * colSpacing,
      y: bottomRailY + 15,
      type: 'power',
    });
  }

  return pins;
};

